-- Reference SQL for migration 0013; do not run beside vnfest-migrate.
CREATE TABLE IF NOT EXISTS spy_rooms (id INT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(16) NOT NULL, name VARCHAR(80) NOT NULL DEFAULT '', host_user_id INT NOT NULL, club_id INT NULL, country VARCHAR(50) NOT NULL DEFAULT 'china', cap INT NOT NULL DEFAULT 8, joined INT NOT NULL DEFAULT 0, dist_civilian INT NOT NULL DEFAULT 0, dist_spy INT NOT NULL DEFAULT 0, dist_blank INT NOT NULL DEFAULT 0, phase VARCHAR(16) NOT NULL DEFAULT 'lobby', round INT NOT NULL DEFAULT 1, timer_profile VARCHAR(16) NOT NULL DEFAULT 'standard', deadline_at BIGINT NOT NULL DEFAULT 0, speaker_seat INT NOT NULL DEFAULT 0, vote_sealed_at BIGINT NOT NULL DEFAULT 0, revote_used TINYINT NOT NULL DEFAULT 0, spectate TINYINT NOT NULL DEFAULT 1, spectate_delay INT NOT NULL DEFAULT 60, need_code TINYINT NOT NULL DEFAULT 0, join_code VARCHAR(16) NOT NULL DEFAULT '', word_a VARCHAR(64) NOT NULL DEFAULT '', word_b VARCHAR(64) NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'waiting', winner VARCHAR(16) NOT NULL DEFAULT '', host_last_seen_at BIGINT NOT NULL DEFAULT 0, rev BIGINT NOT NULL DEFAULT 1, last_activity_at BIGINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_spy_room_code (code));
CREATE TABLE IF NOT EXISTS spy_seats (id INT PRIMARY KEY AUTO_INCREMENT, room_id INT NOT NULL, seat INT NOT NULL, user_id INT NULL, nick VARCHAR(64) NOT NULL DEFAULT '', avatar VARCHAR(255) NOT NULL DEFAULT '', role VARCHAR(16) NOT NULL DEFAULT '', role_preset VARCHAR(16) NOT NULL DEFAULT '', ready_at BIGINT NOT NULL DEFAULT 0, viewed_at BIGINT NOT NULL DEFAULT 0, out_round INT NULL, out_by VARCHAR(16) NOT NULL DEFAULT '', last_seen_at BIGINT NOT NULL DEFAULT 0, joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_spy_seat (room_id,seat), UNIQUE KEY uq_spy_seat_user (room_id,user_id));
CREATE TABLE IF NOT EXISTS spy_words (room_id INT NOT NULL PRIMARY KEY, pair_id INT NOT NULL DEFAULT 0, civilian_word VARCHAR(64) NOT NULL DEFAULT '', spy_word VARCHAR(64) NOT NULL DEFAULT '', difficulty VARCHAR(16) NOT NULL DEFAULT 'mid', similarity VARCHAR(16) NOT NULL DEFAULT 'near', dealt_at BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS spy_word_pairs (id INT PRIMARY KEY AUTO_INCREMENT, a VARCHAR(64) NOT NULL, b VARCHAR(64) NOT NULL, level VARCHAR(16) NOT NULL DEFAULT 'mid', similarity VARCHAR(16) NOT NULL DEFAULT 'near', used_count INT NOT NULL DEFAULT 0, enabled TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_spy_pair (a,b));
CREATE TABLE IF NOT EXISTS spy_sentences (id INT PRIMARY KEY AUTO_INCREMENT, room_id INT NOT NULL, round INT NOT NULL, seat INT NOT NULL, body VARCHAR(160) NOT NULL, skipped TINYINT NOT NULL DEFAULT 0, submitted_at BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_spy_sentence (room_id,round,seat));
CREATE TABLE IF NOT EXISTS spy_votes (id INT PRIMARY KEY AUTO_INCREMENT, room_id INT NOT NULL, round INT NOT NULL, from_seat INT NOT NULL, to_seat INT NULL, sealed TINYINT NOT NULL DEFAULT 0, submitted_at BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_spy_vote (room_id,round,from_seat));
CREATE TABLE IF NOT EXISTS spy_night_actions (id INT PRIMARY KEY AUTO_INCREMENT, room_id INT NOT NULL, round INT NOT NULL, from_seat INT NOT NULL, target_seat INT NULL, submitted_at BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_spy_night (room_id,round,from_seat));
CREATE TABLE IF NOT EXISTS spy_blank_guesses (id INT PRIMARY KEY AUTO_INCREMENT, room_id INT NOT NULL, round INT NOT NULL, seat INT NOT NULL, guess_a VARCHAR(64) NOT NULL DEFAULT '', guess_b VARCHAR(64) NOT NULL DEFAULT '', hit_a TINYINT NOT NULL DEFAULT 0, hit_b TINYINT NOT NULL DEFAULT 0, result VARCHAR(16) NOT NULL DEFAULT '', host_confirmed TINYINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_spy_blank_guess (room_id,seat));
CREATE TABLE IF NOT EXISTS spy_round_outcomes (id INT PRIMARY KEY AUTO_INCREMENT, room_id INT NOT NULL, round INT NOT NULL, stage VARCHAR(16) NOT NULL, eliminated_seat INT NULL, eliminated_role VARCHAR(16) NOT NULL DEFAULT '', out_by VARCHAR(16) NOT NULL DEFAULT '', tie TINYINT NOT NULL DEFAULT 0, host_ruling VARCHAR(64) NOT NULL DEFAULT '', tally TEXT NULL, created_at BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_spy_round_outcome (room_id,round,stage));
CREATE TABLE IF NOT EXISTS spy_events (id INT PRIMARY KEY AUTO_INCREMENT, room_id INT NOT NULL, rev BIGINT NOT NULL, kind VARCHAR(32) NOT NULL, payload TEXT NULL, created_at BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_spy_event_rev (room_id,rev));
CREATE TABLE IF NOT EXISTS spy_results (room_id INT NOT NULL PRIMARY KEY, winner VARCHAR(16) NOT NULL DEFAULT '', reason VARCHAR(255) NOT NULL DEFAULT '', rounds INT NOT NULL DEFAULT 0, awards TEXT NULL, reveal TEXT NULL, settled_at BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS spy_idempotency (id INT PRIMARY KEY AUTO_INCREMENT, idem_key VARCHAR(64) NOT NULL, room_id INT NOT NULL DEFAULT 0, response TEXT NULL, created_at BIGINT NOT NULL DEFAULT 0, expires_at BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_spy_idem (idem_key));
